using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class RebirthCamperStandingClearance{public static void RunBatch(){var root=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/REBIRTHCamperCampIntegrated_20261014/rebirthCamper80s.prefab");var lines=new List<string>{"z,floor,ceiling,clearance"};foreach(float z in new[]{-3.1f,-2.8f,-2.4f,-2f,-1.6f}){var ys=new List<float>();var names=new List<string>();foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name=="camper_interior"||f.name=="camper_body")){var v=f.sharedMesh.vertices;var t=f.sharedMesh.triangles;for(int i=0;i<t.Length;i+=3){var a=f.transform.TransformPoint(v[t[i]]);var b=f.transform.TransformPoint(v[t[i+1]]);var c=f.transform.TransformPoint(v[t[i+2]]);if(Mathf.Abs(Vector3.Cross(b-a,c-a).normalized.y)<.8f)continue;float det=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(det)<.000001f)continue;float u=((b.z-c.z)*(-c.x)+(c.x-b.x)*(z-c.z))/det;float w=((c.z-a.z)*(-c.x)+(a.x-c.x)*(z-c.z))/det;float q=1-u-w;if(u<0||w<0||q<0)continue;ys.Add(u*a.y+w*b.y+q*c.y);names.Add(f.name);}}float floor=ys.Where(y=>y>.3f&&y<1.1f).DefaultIfEmpty(float.NaN).Max();float ceiling=ys.Where(y=>y>2f&&y<3f).DefaultIfEmpty(float.NaN).Min();lines.Add(z+","+floor+","+ceiling+","+(ceiling-floor)+","+(ys.Contains(floor)?names[ys.IndexOf(floor)]:"none")+","+(ys.Contains(ceiling)?names[ys.IndexOf(ceiling)]:"none"));}File.WriteAllLines("E:/_Haven/shared/REBIRTHTemp/CamperStandingClearance_20261014/cabin-measurements.csv",lines);}}

